using System;using System.Data.SqlClient;
namespace AshkanPharmacy.Core { public sealed class OperationalHealth {public bool Database{get;set;}public int LowStock{get;set;}public int NearExpiry{get;set;}public DateTime CheckedAt{get;set;}}
 public static class OperationalHealthService { public static OperationalHealth Check(){var h=new OperationalHealth{Database=Database.IsAvailable,CheckedAt=DateTime.Now};if(!h.Database)return h;try{using(var c=Database.Open()){using(var q=new SqlCommand("SELECT COUNT(*) FROM dbo.Medicines WHERE Stock<=MinStock",c))h.LowStock=Convert.ToInt32(q.ExecuteScalar());using(var q=new SqlCommand("SELECT COUNT(*) FROM dbo.MedicineBatches WHERE Quantity>0 AND ExpiryDate>=GETDATE() AND ExpiryDate<DATEADD(day,60,GETDATE())",c))h.NearExpiry=Convert.ToInt32(q.ExecuteScalar());}}catch{h.Database=false;}return h;} } }